import { expect, test } from './fixtures';

/**
 * SETTINGS, one page (card c171), its `full` state at tablet portrait, in a real browser.
 *
 * Generated by design-tools/gen-conformance.mjs from the design handoff, and
 * checked in deliberately. These assert the frame and the measurements — the
 * part visual review reliably misses. The numbers are hand-set in the mock and
 * do not round to a spacing ladder, so a later pass that tidies them would
 * silently redraw the screen. That is what this is here to stop; it is not
 * pedantry.
 *
 * Source: doc/design/handoff/Settings.dc.html. 07 — BROWSE isn't mapped: the shared
 * e2e server has no engine, so the section isn't drawn (browse-extensions.e2e.ts
 * covers it).
 * Extracted at 2026-10-29T22:34:17.911Z at 1440x2400.
 *
 * Regenerating overwrites this file. Hand edits belong in a sibling spec.
 */

const base = process.env.PLAYWRIGHT_BASE_URL ?? '';

const SEL = {
	frame: 'body',
	region1: '.bar .back',
	region2: '.legend',
	region3: '.legend .lg:nth-child(1)',
	region4: '.legend .lg:nth-child(2)',
	region5: '.legend .lg:nth-child(3)',
	region6: '#s-images .sec-head',
	region7: '#s-images .zooms',
	region8: '#s-novels .sec-head',
	region9: '#s-watching .sec-head',
	region10: '#s-downloading .sec-head',
	region11: '#s-library .sec-head',
	region12: '#s-catalogues .sec-head',
	region14: '#s-devices .sec-head'
};

test('SETTINGS: frame matches the handoff', async ({ page }) => {
	await page.goto(`${base}/settings`);
	await expect(page.locator(SEL.frame)).toBeVisible();

	const frameStyle = await page.locator(SEL.frame).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display
		};
	});
	expect(frameStyle.display).toBe('block');
});

test('SETTINGS: region1 matches the handoff', async ({ page }) => {
	await page.goto(`${base}/settings`);
	await expect(page.locator(SEL.region1)).toBeVisible();

	const region1Style = await page.locator(SEL.region1).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display,
			alignItems: cs.alignItems,
			rowGap: cs.rowGap,
			columnGap: cs.columnGap,
			paddingTop: cs.paddingTop,
			paddingRight: cs.paddingRight,
			paddingBottom: cs.paddingBottom,
			paddingLeft: cs.paddingLeft,
			borderRightWidth: cs.borderRightWidth,
			fontSize: cs.fontSize,
			fontWeight: cs.fontWeight,
			letterSpacing: cs.letterSpacing,
			lineHeight: cs.lineHeight
		};
	});
	expect(region1Style.display).toBe('flex');
	expect(region1Style.alignItems).toBe('center');
	expect(region1Style.rowGap).toBe('14px');
	expect(region1Style.columnGap).toBe('14px');
	expect(region1Style.paddingTop).toBe('0px');
	expect(region1Style.paddingRight).toBe('24px');
	expect(region1Style.paddingBottom).toBe('0px');
	expect(region1Style.paddingLeft).toBe('24px');
	expect(region1Style.borderRightWidth).toBe('1px');
	expect(region1Style.fontSize).toBe('14px');
	expect(region1Style.fontWeight).toBe('500');
	expect(region1Style.letterSpacing).toBe('0.56px'); // authored 0.04em
	expect(region1Style.lineHeight).toBe('normal');
});

